// ExecutorServiceServer is the server API for ExecutorService service.
// All implementations must embed UnimplementedExecutorServiceServer
// for forward compatibility.
//
// ExecutorService is served by nebula-executor on a Unix domain socket only.
// Every method is authorized by the caller's kernel-reported UID
// (SO_PEERCRED); see internal/peercred for the method-to-role table.
//
// Compatibility rules: fields are never renumbered or reused; removed fields
// are reserved. New methods require an explicit entry in the role table,
// otherwise they are denied for everyone.
type ExecutorServiceServer interface {
	// Role: server, admin.
	GetStatus(context.Context, *GetStatusRequest) (*GetStatusResponse, error)
	// Role: server. Submits a fully resolved execution request. The executor
	// canonicalizes it (RFC 8785), computes the digest itself and returns the
	// approval challenge. For LOW risk inside an active privileged session the
	// permit is issued immediately.
	ProposeExecution(context.Context, *ProposeExecutionRequest) (*ProposeExecutionResponse, error)
	// Role: server. Relays a WebAuthn assertion over the challenge returned by
	// ProposeExecution. The executor verifies it on its own.
	SubmitAssertion(context.Context, *SubmitAssertionRequest) (*SubmitAssertionResponse, error)
	// Role: server. Starts and completes the privileged web session, which
	// requires a user-verified assertion.
	BeginPrivilegedSession(context.Context, *BeginPrivilegedSessionRequest) (*BeginPrivilegedSessionResponse, error)
	CompletePrivilegedSession(context.Context, *CompletePrivilegedSessionRequest) (*CompletePrivilegedSessionResponse, error)
	// Role: server. Asks whether one host run is covered by an issued permit
	// and, if so, reserves the host (one use per host). The executor hashes
	// the artifact and parameters itself. Refused (stage_plan_invalid) for a
	// permit proposed with a stage plan: nothing would record the host's
	// outcome, so its stage could never pass or be skipped.
	AuthorizeRun(context.Context, *AuthorizeRunRequest) (*AuthorizeRunResponse, error)
	// Role: server. Authorizes one host run exactly like AuthorizeRun and
	// runs it attached on the pinned host (spec 07, Milestone 4): the
	// executor connects with the pin's credential (which must be the run's),
	// sends the parameters it holds from the proposal and the artifact, and
	// returns the bounded result and log. The permit's host is used once the
	// run is authorized, whatever the outcome.
	RunAttached(context.Context, *RunAttachedRequest) (*RunAttachedResponse, error)
	// Role: server. Authorizes one host run like RunAttached and starts it
	// as a durable job (spec 07): recorded in executor.db before anything
	// is sent, dispatched once, then only observed. The executor reconciles
	// open runs in the background (also after a restart, once unlocked) and
	// never dispatches a run again.
	StartDurable(context.Context, *StartDurableRequest) (*StartDurableResponse, error)
	// Role: server. The state of a durable run; with release, a finished
	// run's result and log are dropped from executor.db after this answer.
	GetRun(context.Context, *GetRunRequest) (*GetRunResponse, error)
	// Role: admin. Decrypts the SSH keys into the in-process keyring and,
	// once initialized, the vault's master key (spec 06: one passphrase is
	// tried on both; the scope retries one of them alone).
	Unlock(context.Context, *UnlockRequest) (*UnlockResponse, error)
	// Role: server, admin. Wipes the keyring and the vault key and ends the
	// privileged session.
	// Locking is always permitted because it only reduces capability.
	Lock(context.Context, *LockRequest) (*LockResponse, error)
	// Role: admin. Lists pending permits with the executor's own view of them,
	// so that `nebula approve` never relies on what the web UI displayed.
	ListPending(context.Context, *ListPendingRequest) (*ListPendingResponse, error)
	// Role: admin. Hardened approval path.
	ApproveCLI(context.Context, *ApproveCLIRequest) (*ApproveCLIResponse, error)
	// Role: server, admin. Read-only: the state of the live permit for the
	// given execution digest, so the server can see an approval made on the
	// executor host (spec 05, hardened path). Returns UNSPECIFIED when there
	// is no live permit (never proposed, expired, consumed, revoked by Lock).
	// Reveals nothing about the permit's contents and changes nothing.
	GetPermitState(context.Context, *GetPermitStateRequest) (*GetPermitStateResponse, error)
	// Role: admin. Trusts an artifact for one action and version at a
	// declared risk. The executor hashes the bytes itself. Replaces an
	// earlier entry for the same artifact, action and version.
	TrustArtifact(context.Context, *TrustArtifactRequest) (*TrustArtifactResponse, error)
	// Role: admin. Withdraws trust; the artifact is HIGH again.
	UntrustArtifact(context.Context, *UntrustArtifactRequest) (*UntrustArtifactResponse, error)
	// Role: admin.
	ListTrustedArtifacts(context.Context, *ListTrustedArtifactsRequest) (*ListTrustedArtifactsResponse, error)
	// Role: admin. Sets the executor's criticality of a host, bound to its
	// pinned key fingerprint, or removes the record (clear). A target counts
	// as recorded only if host ID and fingerprint both match.
	SetHostCriticality(context.Context, *SetHostCriticalityRequest) (*SetHostCriticalityResponse, error)
	// Role: admin.
	ListHostCriticality(context.Context, *ListHostCriticalityRequest) (*ListHostCriticalityResponse, error)
	// Role: admin. Creates a single-use code for the next registration
	// (15 minutes); replaces an unused earlier code.
	CreateRegistrationCode(context.Context, *CreateRegistrationCodeRequest) (*CreateRegistrationCodeResponse, error)
	// Role: server. Starts a registration and returns the WebAuthn options.
	BeginRegistration(context.Context, *BeginRegistrationRequest) (*BeginRegistrationResponse, error)
	// Role: server. Completes a registration. Single use: the registration is
	// consumed whether or not it succeeds.
	FinishRegistration(context.Context, *FinishRegistrationRequest) (*FinishRegistrationResponse, error)
	// Role: admin.
	ListWebAuthnCredentials(context.Context, *ListWebAuthnCredentialsRequest) (*ListWebAuthnCredentialsResponse, error)
	// Role: admin. Removes a credential and locks the executor (ends the
	// privileged session, revokes every permit, cancels pending
	// registrations and the outstanding code).
	RemoveWebAuthnCredential(context.Context, *RemoveWebAuthnCredentialRequest) (*RemoveWebAuthnCredentialResponse, error)
	// Role: server. Starts a login (single-use challenge, 2 minutes).
	BeginLogin(context.Context, *BeginLoginRequest) (*BeginLoginResponse, error)
	// Role: server. Completes a login; the login is consumed whether or not
	// it succeeds.
	FinishLogin(context.Context, *FinishLoginRequest) (*FinishLoginResponse, error)
	// Role: server. Reports whether a credential is still registered, so the
	// server can end web sessions opened with a credential that was removed.
	CheckCredential(context.Context, *CheckCredentialRequest) (*CheckCredentialResponse, error)
	// Role: admin. Creates a new, not yet active TOTP secret (replaces an
	// earlier one) and returns it for the authenticator app.
	BeginTOTPSetup(context.Context, *BeginTOTPSetupRequest) (*BeginTOTPSetupResponse, error)
	// Role: admin. Activates the new secret with one current code from the app.
	ConfirmTOTPSetup(context.Context, *ConfirmTOTPSetupRequest) (*ConfirmTOTPSetupResponse, error)
	// Role: admin.
	RemoveTOTP(context.Context, *RemoveTOTPRequest) (*RemoveTOTPResponse, error)
	// Role: admin.
	GetTOTPStatus(context.Context, *GetTOTPStatusRequest) (*GetTOTPStatusResponse, error)
	// Role: server. Verifies a recovery code (single use, rate limited). On
	// success the executor ends the privileged session, revokes permits and
	// enters the recovery state.
	RecoveryLogin(context.Context, *RecoveryLoginRequest) (*RecoveryLoginResponse, error)
	// Role: admin. Ends a pending recovery after the admin confirmed, on the
	// executor host, that the given credential (registered after the
	// recovery login) is their own new key.
	FinishRecovery(context.Context, *FinishRecoveryRequest) (*FinishRecoveryResponse, error)
	// Role: admin. Reads the host key of one endpoint without sending a user
	// name or credential.
	ProbeHostKey(context.Context, *ProbeHostKeyRequest) (*ProbeHostKeyResponse, error)
	// Role: admin. Pins a host key and binds the host to one SSH user and one
	// credential reference. A host that is already pinned must be unpinned
	// first.
	PinHostKey(context.Context, *PinHostKeyRequest) (*PinHostKeyResponse, error)
	// Role: admin. Removes a pin (and a mismatch block with it); the host
	// cannot be connected until it is pinned again.
	UnpinHostKey(context.Context, *UnpinHostKeyRequest) (*UnpinHostKeyResponse, error)
	// Role: server, admin. Lists the pins; public data only.
	ListHostKeys(context.Context, *ListHostKeysRequest) (*ListHostKeysResponse, error)
	// Role: server. Proposes re-pinning a host blocked by a host key
	// mismatch to the key it presented (spec 08: a HIGH action with user
	// verification). The executor builds the request from its own block
	// record (host, pinned and presented fingerprint, endpoint, block time);
	// the caller names only the host. Approve it like any permit
	// (SubmitAssertion or `nebula approve`), then call CommitRepin.
	ProposeRepin(context.Context, *ProposeRepinRequest) (*ProposeRepinResponse, error)
	// Role: server. Carries out an approved re-pin: the block must still be
	// the approved one, and the endpoint must still present the approved
	// key, which then replaces the pin (with the host's criticality record).
	CommitRepin(context.Context, *CommitRepinRequest) (*CommitRepinResponse, error)
	// Role: server. Bulk enrollment (spec 08): reads the host keys of new
	// hosts and proposes pinning them, as one HIGH action with user
	// verification. The executor probes the endpoints itself; the approval
	// binds host, endpoint, fingerprint, SSH user and credential of every
	// host. Hosts pinned this way get no criticality record (they count as
	// HIGH until an admin sets one on the executor host).
	ProposeEnroll(context.Context, *ProposeEnrollRequest) (*ProposeEnrollResponse, error)
	// Role: server. Pins the hosts of an approved enrollment whose endpoint
	// still presents the approved key, and tries a login when the keys are
	// unlocked.
	CommitEnroll(context.Context, *CommitEnrollRequest) (*CommitEnrollResponse, error)
	// Role: admin. Returns the public half of a loaded SSH key (the keyring
	// must be unlocked), for the enrollment script.
	GetSSHPublicKey(context.Context, *GetSSHPublicKeyRequest) (*GetSSHPublicKeyResponse, error)
	// Role: admin. Connects to a pinned host with its credential (the keyring
	// must be unlocked) over the given endpoints, in order, and disconnects.
	// A host key mismatch blocks the host.
	TestConnection(context.Context, *TestConnectionRequest) (*TestConnectionResponse, error)
	// Vault (spec 06): secrets that are not SSH keys. No RPC returns a
	// secret value; the executor decrypts them only for its own runs.
	// Role: admin. Creates the vault under a passphrase (at least 32
	// characters) and leaves it unlocked.
	InitVault(context.Context, *InitVaultRequest) (*InitVaultResponse, error)
	// Role: admin. Stores a secret as a new version (vault unlocked).
	SetSecret(context.Context, *SetSecretRequest) (*SetSecretResponse, error)
	// Role: admin. Lists secret IDs and versions, never values.
	ListSecrets(context.Context, *ListSecretsRequest) (*ListSecretsResponse, error)
	// Role: admin. Deletes a secret (vault unlocked).
	DeleteSecret(context.Context, *DeleteSecretRequest) (*DeleteSecretResponse, error)
	// Stage engine (spec 07, Milestone 6). A permit proposed with a stage
	// plan runs stage by stage: the executor refuses a host whose stage is
	// not open, stops the rollout when a stage has more failed hosts than
	// its plan allows, and opens a later stage only through a gate (or by
	// itself, for a LOW or MEDIUM plan that says auto). The outcomes it
	// decides on are its own run records.
	//
	// Role: server. Checks a gate (open the next stage, skip a host) and
	// returns what it needs: nothing beyond the privileged session for LOW
	// and MEDIUM, a fresh user-verified assertion over a challenge bound to
	// digest and gate for HIGH and CRITICAL, the CLI in hardened mode.
	BeginGate(context.Context, *BeginGateRequest) (*BeginGateResponse, error)
	// Role: server. Applies a gate with the privileged session and, for HIGH
	// and CRITICAL, the assertion over BeginGate's challenge (single use).
	CommitGate(context.Context, *CommitGateRequest) (*CommitGateResponse, error)
	// Role: server. Stops a rollout: no further host is authorized. Needs no
	// approval, since it only takes permission away.
	AbortRollout(context.Context, *AbortRolloutRequest) (*AbortRolloutResponse, error)
	// Role: server, admin. The executor's view of a rollout.
	GetRollout(context.Context, *GetRolloutRequest) (*GetRolloutResponse, error)
	// Role: admin. Hardened gate path (`nebula approve --stage`, `--skip`).
	ApproveGateCLI(context.Context, *ApproveGateCLIRequest) (*ApproveGateCLIResponse, error)
	// Trust an artifact from the browser (M7-4). Role: server. The executor
	// hashes the bytes and binds a fresh user-verified assertion to (hash,
	// action, version, risk); needs the privileged session; hardened mode
	// refuses (cli_required) and keeps `nebula artifact trust`.
	BeginTrustArtifact(context.Context, *BeginTrustArtifactRequest) (*BeginTrustArtifactResponse, error)
	CommitTrustArtifact(context.Context, *CommitTrustArtifactRequest) (*CommitTrustArtifactResponse, error)
	// Role: server, admin. Whether the executor trusts these bytes as this
	// action and version, and at which risk.
	GetArtifactTrust(context.Context, *GetArtifactTrustRequest) (*GetArtifactTrustResponse, error)
	// Signed modules (M7-5). Role: server. The executor verifies the lock's
	// SSH signature (namespace nebula-module) by a trusted signer, checks
	// each script against the lock, builds each action's artifact itself and
	// trusts it at the action's risk. Refused when the module was signed by
	// another signer before (signer_changed) or the version's lock changed.
	RegisterModule(context.Context, *RegisterModuleRequest) (*RegisterModuleResponse, error)
	// Role: admin (`nebula signer …`). Adding a signer is CRITICAL: the CLI
	// asks for the fingerprint to be typed.
	AddSigner(context.Context, *AddSignerRequest) (*AddSignerResponse, error)
	RemoveSigner(context.Context, *RemoveSignerRequest) (*RemoveSignerResponse, error)
	ConfirmModuleSigner(context.Context, *ConfirmModuleSignerRequest) (*ConfirmModuleSignerResponse, error)
	// Role: server, admin.
	ListSigners(context.Context, *ListSignersRequest) (*ListSignersResponse, error)
	// Schedule grants (docs/implementation/schedule-grants.md): standing
	// permission, approved with the security key, to run fixed actions that
	// the executor rates LOW on fixed hosts at most once per interval, until
	// the grant expires or is revoked.
	//
	// Role: server. Checks a grant document (privileged session required)
	// and returns the challenge to approve it.
	ProposeScheduleGrant(context.Context, *ProposeScheduleGrantRequest) (*ProposeScheduleGrantResponse, error)
	// Role: server. Approves a proposed grant with a user-verified assertion.
	CommitScheduleGrant(context.Context, *CommitScheduleGrantRequest) (*CommitScheduleGrantResponse, error)
	// Role: admin. Lists proposed grants (`nebula schedule pending`).
	ListPendingScheduleGrants(context.Context, *ListPendingScheduleGrantsRequest) (*ListPendingScheduleGrantsResponse, error)
	// Role: admin. Hardened approval path (`nebula schedule approve`).
	ApproveScheduleGrantCLI(context.Context, *ApproveScheduleGrantCLIRequest) (*ApproveScheduleGrantCLIResponse, error)
	// Role: server, admin.
	ListScheduleGrants(context.Context, *ListScheduleGrantsRequest) (*ListScheduleGrantsResponse, error)
	// Role: server, admin. Needs no approval.
	RevokeScheduleGrant(context.Context, *RevokeScheduleGrantRequest) (*RevokeScheduleGrantResponse, error)
	// Role: server. Runs one host run under a grant, attached, like
	// RunAttached: the grant must cover action, artifact, parameters and the
	// pinned host, the action must still be LOW there, and the interval must
	// have passed.
	RunScheduled(context.Context, *RunScheduledRequest) (*RunScheduledResponse, error)
	// Read grants (ADR 0007). These methods use read-grant-v2 authority;
	// legacy read-schedule-v1 signatures never authorize on-demand reads.
	// Role: server. Proposes a bounded, frozen document without a session.
	ProposeReadGrant(context.Context, *ProposeReadGrantRequest) (*ProposeReadGrantResponse, error)
	// Role: server. Relays a fresh user-verified assertion; the executor
	// verifies the grant-bound challenge. This is never a server approval.
	// Hardened mode rejects browser approval and requires the local CLI.
	CommitReadGrant(context.Context, *CommitReadGrantRequest) (*CommitReadGrantResponse, error)
	// Role: admin. Retrieves the complete frozen scope for local review.
	ListPendingReadGrants(context.Context, *ListPendingReadGrantsRequest) (*ListPendingReadGrantsResponse, error)
	// Role: admin only. Approves the locally reviewed digest.
	ApproveReadGrantCLI(context.Context, *ApproveReadGrantCLIRequest) (*ApproveReadGrantCLIResponse, error)
	// Role: server, admin. Lists complete approved read grants.
	ListReadGrants(context.Context, *ListReadGrantsRequest) (*ListReadGrantsResponse, error)
	// Role: server, admin. Reduces authority, without an assertion.
	RevokeReadGrant(context.Context, *RevokeReadGrantRequest) (*RevokeReadGrantResponse, error)
	// Role: server. One exact read with a fresh executor-generated execution
	// ID. Both triggers share authorization, budget, revocation and dispatch
	// checks. The trigger selects work inside the approved scope only.
	RunReadGrant(context.Context, *RunReadGrantRequest) (*RunReadGrantResponse, error)
	// Signed events (M10-1). Role: server, admin. Read-only: the chain of
	// the executor's audit events with the key to verify it.
	ListEvents(context.Context, *ListEventsRequest) (*ListEventsResponse, error)
	// Backup (M10-2). Role: admin. The executor's part of `nebula backup`:
	// a checked snapshot of executor.db and the encrypted SSH key files.
	BackupExecutor(context.Context, *BackupExecutorRequest) (*BackupExecutorResponse, error)
	// Local PVE credential administration. Role: admin for every method.
	ProbePVERemote(context.Context, *ProbePVERemoteRequest) (*ProbePVERemoteResponse, error)
	AddPVERemote(context.Context, *AddPVERemoteRequest) (*AddPVERemoteResponse, error)
	RotatePVEToken(context.Context, *RotatePVETokenRequest) (*RotatePVETokenResponse, error)
	RemovePVERemote(context.Context, *RemovePVERemoteRequest) (*RemovePVERemoteResponse, error)
	ListPVEAdminRemotes(context.Context, *ListPVEAdminRemotesRequest) (*ListPVEAdminRemotesResponse, error)
	// Proposes a HIGH permit bound to current trust, endpoints and credentials.
	ProposePVERepin(context.Context, *ProposePVERepinRequest) (*ProposePVERepinResponse, error)
	CommitPVERepin(context.Context, *CommitPVERepinRequest) (*CommitPVERepinResponse, error)
	// PVE provider reads (ADR 0006, P1-05). Role: server, admin,
	// pve-collector. Metadata only: which remotes exist, their kind, ordered
	// endpoints, trust generation and state. The trust pin is a SHA-256
	// fingerprint — a trust identifier, not a secret. No credentials, no
	// trust material, no raw API output.
	ListPVERemotes(context.Context, *ListPVERemotesRequest) (*ListPVERemotesResponse, error)
	// PVE provider reads (ADR 0006, P1-05). Role: admin, pve-collector. One
	// typed read against one remote. The server never calls this: it writes
	// poll requests to the spool and the pve-collector schedules the reads.
	// There is no generic HTTP proxy and no method reveals secrets. The
	// executor validates remote_id, method and parameter shape and returns
	// InvalidArgument for malformed requests. Each read needs an active
	// provider read grant (read-grant-v2, rate_profile "provider", ADR 0007
	// E08) naming the remote's current trust pin, trust generation and read
	// credential version and the method; it spends that grant's per-method
	// interval and per-remote request budget. NODES, GUESTS, STORAGE and
	// CLUSTER are wired; the other methods answer Unimplemented.
	ReadPVE(context.Context, *ReadPVERequest) (*ReadPVEResponse, error)
	mustEmbedUnimplementedExecutorServiceServer()
}

